input double    LotSize        = 0.01;          // Tamanho padrão da operação
input int       MagicNumber    = 123456;        // Número mágico para identificar suas ordens
input bool      EnableTrading  = true;          // Habilitar/Desabilitar operações

input group "Fibonacci e Zonas"
input double    FibEntryMin    = 0.382;         // Entrada mínima de Fib
input double    FibEntryMax    = 0.618;         // Entrada máxima de Fib (para retratação)
input int       BarsLookBack   = 50;            // Olhar X velas atrás para definir zona

input group "Gestão de Risco"
input double    TP_Points      = 20;            // Alvo de lucro em pontos (ou pips se configurado)
input int       SL_Points      = 10;            // Stop Loss inicial em pontos
input double    RiskPercent    = 1.0;           // Risco em % do capital
input int       TrailingStart  = 30;            // Pontos para ativar trailing
input int       TrailingStep   = 10;            // Passo do trailing

//--- Variáveis Globais
CTrade trade;
int last_order_id = 0;
bool trend_up = false;
bool trend_down = false;
double current_price = 0;
string name_ob = "";
string name_fvg = "";

//+------------------------------------------------------------------+
//| Expert initialization function                                   |
//+------------------------------------------------------------------+
int OnInit()
{
   trade.SetExpertMagicNumber(MagicNumber);
   Print("EA Inicializado: SMC Fib AutoTrader v1.0");

   // Verificar se há indicadores carregados (opcional, aqui usaremos funções internas)
   return(INIT_SUCCEEDED);
}

//+------------------------------------------------------------------+
//| Expert deinitialization function                                 |
//+------------------------------------------------------------------+
void OnDeinit(const int reason)
{
   Comment("");
   Print("EA Desativado.");
}

//+------------------------------------------------------------------+
//| Expert tick function                                             |
//+------------------------------------------------------------------+
void OnTick()
{
   current_price = SymbolInfoDouble(_Symbol, SYMBOL_BID);

   // Atualizar status da tendência baseado na última vela fechada
   UpdateTrend();

   if(EnableTrading)
   {
      CheckAndOpenOrder();
   }
}

//+------------------------------------------------------------------+
//| Função para determinar a Tendência                                |
//+------------------------------------------------------------------+
void UpdateTrend()
{
   int lookback = BarsLookBack;
   double open_high = iHigh(_Symbol, Period, lookback);
   double open_low = iLow(_Symbol, Period, lookback);
   double close_val = iClose(_Symbol, Period, 1);

   // Simplificação: Tendencia baseada no movimento recente de HH/HL ou LL/LH
   // Aqui usaremos uma verificação simples de preço atual vs média móvel ou swing recente
   // Para SMC puro, idealmente verificamos a estrutura mais ampla.

   double ma_50 = iMA(_Symbol, 0, 50, 0, MODE_SMA, PRICE_CLOSE);
   double ma_200 = iMA(_Symbol, 0, 200, 0, MODE_SMA, PRICE_CLOSE);

   if(ma_50[0] > ma_200[0])
      trend_up = true;
   else
      trend_up = false;

   // Resetar se houver mudança brusca (simplificado)
   if(trend_up && ma_50[0] < ma_200[0]) trend_up = false;
   if(!trend_up && ma_50[0] > ma_200[0]) trend_up = true;
}

//+------------------------------------------------------------------+
//| Função Principal de Trade Logic                                  |
//+------------------------------------------------------------------+
void CheckAndOpenOrder()
{
   // Calcular Fibonacci
   double fib_start = iHigh(_Symbol, Period, BarsLookBack);
   double fib_end = iLow(_Symbol, Period, BarsLookBack);

   // Se for tendência de alta, queremos comprar na retratação (Topo do Fib)
   // Se for tendência de baixa, queremos vender na retratação (Fundo do Fib)

   if(trend_up)
   {
      // Comprar na Zona de Fib (Retração)
      if(FibCheck(fib_start, fib_end, FibEntryMin, FibEntryMax))
      {
         double entry_price = Ask;
         double tp = entry_price + TP_Points * _Point;
         double sl = entry_price - SL_Points * _Point;

         // Checar se já existe ordem de compra aberta recentemente (evitar duplo buy)
         if(!IsPositionOpen(Symbol, OP_BUY, MagicNumber))
         {
            double volume = CalculateLot(RiskPercent);

            // Verificar Liquidez Simples (Preço acima de Swing Low recente)
            if(current_price > iLow(_Symbol, Period, 100)) 
            {
               trade.Buy(LotSize, entry_price, sl, tp, "SMC BUY Fib Retracement");
               last_order_id = trade.LastOrder();
            }
         }
      }
   }
   else
   {
      // Vender na Zona de Fib (Retração)
      if(FibCheck(fib_start, fib_end, FibEntryMin, FibEntryMax))
      {
         double entry_price = Bid;
         double tp = entry_price - TP_Points * _Point;
         double sl = entry_price + SL_Points * _Point;

         if(!IsPositionOpen(Symbol, OP_SELL, MagicNumber))
         {
            double volume = CalculateLot(RiskPercent);

            // Verificar Liquidez Simples (Preço abaixo de Swing High recente)
            if(current_price < iHigh(_Symbol, Period, 100))
            {
               trade.Sell(LotSize, entry_price, sl, tp, "SMC SELL Fib Retracement");
               last_order_id = trade.LastOrder();
            }
         }
      }
   }
}

//+------------------------------------------------------------------+
//| Verifica se o preço está dentro da zona de Fib desejada         |
//+------------------------------------------------------------------+
bool FibCheck(double high, double low, double min_level, double max_level)
{
   double range = high - low;
   double start = high; // Topo
   double end = low;    // Fundo

   // Calcular níveis
   double level_38 = start - (range * (1 - min_level)); // Ex: 38.2% do caminho
   double level_50 = start - (range * (1 - 0.50));     // 50%
   double level_61 = start - (range * (1 - max_level)); // 61.8%

   // Ajuste conforme direção da tendência
   // Se Trend Up, compramos entre 38.2% e 61.8% do caminho descendo
   // Se Trend Down, vendemos entre 38.2% e 61.8% do caminho subindo

   double target_low = start - (range * (1 - min_level));
   double target_high = start - (range * (1 - max_level));

   double current_zone_min = target_low;
   double current_zone_max = target_high;

   if(current_price >= current_zone_min && current_price <= current_zone_max)
   {
      return true;
   }
   return false;
}

//+------------------------------------------------------------------+
//| Calcula o tamanho do lote baseado no risco                       |
//+------------------------------------------------------------------+
double CalculateLot(double risk_percent)
{
   double balance = AccountInfoDouble(ACCOUNT_BALANCE);
   double lot_value = (balance * risk_percent / 100.0) / (_Point * 100); // Ajuste fino necessário dependendo da corretora
   return NormalizeDouble(lot_value, 2);
}

