   // Nota: Este EA abre ordens baseadas em Fib. Para um sistema completo de SMC,
   // o Ideal seria fechar ordens quando o preço fecha uma vela fora de um OB/FVG específico.
   // Aqui faremos um gerenciamento básico de proteção.

   ulong ticket = OrdersSelect(0, true, MagicNumber);
   while(ticket != 0)
