      ENUM_ORDER_TYPE type = OrderType(ticket);

      if(type == OP_BUY)
      {
         // Trailing Stop para Compra
         double stop_loss = OrderGetDouble(ticket, ORDER_SL_PRICE);
         double ask = SymbolInfoDouble(_Symbol, SYMBOL_ASK);

         if(ask - stop_loss >= TrailingStart)
         {
            double new_sl = ask - TrailingStep * _Point;
            OrderModify(ticket, OrderGetDouble(ticket, ORDER_OPEN_PRICE), new_sl, OrderGetDouble(ticket, ORDER_TP_PRICE), TimeCurrent());
         }
      }
      else if(type == OP_SELL)
      {
         // Trailing Stop para Venda
         double stop_loss = OrderGetDouble(ticket, ORDER_SL_PRICE);
         double bid = SymbolInfoDouble(_Symbol, SYMBOL_BID);

         if(stop_loss - bid >= TrailingStart)
         {
            double new_sl = bid + TrailingStep * _Point;
            OrderModify(ticket, OrderGetDouble(ticket, ORDER_OPEN_PRICE), new_sl, OrderGetDouble(ticket, ORDER_TP_PRICE), TimeCurrent());
         }
      }

      ticket = OrdersSelectNext(ticket);
   }
}

//+------------------------------------------------------------------+
