//+------------------------------------------------------------------+
bool IsPositionOpen(string symbol, ENUM_ORDER_TYPE type, int magic)
{
   ulong ticket = OrdersSelect(0, true, magic);
   while(ticket != 0)
   {
      if(OrderGetInteger(ticket, ORDER_SYMBOL) == _Symbol && OrderGetInteger(ticket, ORDER_TYPE) == type)
